<template>
  <div v-if="isPublic || canPublish" class="view-guestbook" :class="{ 'is-exhibition': exhibition }">
    <button v-if="!hideInvitation" type="button" class="guestbook-invitation" @click="open">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15M6 8h3M6 11h3m6-3h3m-3 3h3" /></svg>
      <span>{{ isPublic ? 'Visitors’ notes' : 'Make public' }}</span><span aria-hidden="true" class="guestbook-arrow">↗</span>
    </button>
    <Teleport to="body">
      <dialog v-if="opened" ref="dialog" class="view-dialog guestbook-dialog" aria-labelledby="guestbook-title" @cancel.prevent="close" @keydown.stop>
        <header class="view-dialog-head" :aria-busy="loading">
          <div><h2 id="guestbook-title">Visitors’ notes</h2><span v-if="loading" class="guestbook-loading" role="status" aria-label="Loading notes"></span></div>
          <button class="view-dialog-close" type="button" aria-label="Close visitors’ notes" @click="close"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button>
        </header>
        <form @submit.prevent="submit">
          <textarea :id="`visitor-thought-${exhibition ? 'exhibition' : 'article'}`" v-model="text" rows="3" maxlength="800" aria-label="Your note" placeholder="Your note" required :disabled="sending"></textarea>
          <div class="guestbook-form-foot"><button type="submit" :disabled="sending || !text.trim() || !shareId">{{ sending ? 'Posting…' : 'Post note' }}<span aria-hidden="true">↗</span></button></div>
        </form>
        <p v-if="error" class="guestbook-message" role="status">{{ error }}</p>
        <p v-if="success" class="guestbook-message" role="status">Your note is here. Thank you.</p>
        <div class="guestbook-notes" aria-label="Notes from visitors" :aria-busy="loading">
          <p v-if="!notes.length" class="guestbook-empty" role="status">{{ loading ? 'Loading notes…' : 'Be the first to leave a note.' }}</p>
          <article v-for="note in notes" :key="note.id" class="guestbook-note">
            <p>{{ note.text }}</p><footer><span>{{ note.name || 'A visitor' }}</span><time :datetime="new Date(note.created_at).toISOString()">{{ date(note.created_at) }}</time><button v-if="owned[note.id]" type="button" :disabled="deleting === note.id" @click="remove(note)">{{ deleting === note.id ? 'Removing…' : 'Remove' }}</button></footer>
          </article>
          <button v-if="next" type="button" :disabled="loading" class="guestbook-more" @click="load(true)">Earlier notes <span aria-hidden="true">↓</span></button>
        </div>
      </dialog>
    </Teleport>
  </div>
</template>
<script>
import { askEndpoints } from '../../utils/askSite';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';
export default {
  props: { hideInvitation:Boolean, shareId: { type: String, default: '' }, title: { type: String, default: '' }, exhibition: Boolean, isPublic: Boolean, canPublish: Boolean },
  emits: ['change', 'open', 'close', 'publish'],
  data: () => ({ opened: false, notes: [], count: 0, next: null, text: '', loading: false, sending: false, deleting: '', error: '', success: false, owned: {} }),
  watch: { shareId: { immediate: true, handler() { this.reset(); } }, isPublic() { this.reset(); } },
  mounted() { try { this.owned = JSON.parse(localStorage.getItem('view-note-ownership') || '{}'); } catch { this.owned = {}; } },
  beforeUnmount() { this._closed = true; this._stopBackdrop?.(); if (this.opened) { this.$refs.dialog?.close(); document.body.style.overflow = this._overflow || ''; } },
  methods: {
    reset() { this.notes = []; this.count = 0; this.next = null; this.$emit('change', []); if (this.isPublic && this.shareId) this.load(); if (!this.isPublic && this.opened) this.close(); },
    date(value) { return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(value); },
    async request(options, suffix = '') {
      const endpoint = (process.env.VUE_APP_EXHIBITION_AUDIO_ENDPOINT || askEndpoints()[0]).replace(/\/$/, '');
      const response = await fetch(`${endpoint}/view-notes/${encodeURIComponent(this.shareId)}${suffix}`, { ...options, headers: { 'Content-Type': 'application/json' } });
      if (!response.ok) throw new Error(response.status === 429 ? 'Please give it a moment before leaving another note.' : 'The guestbook is temporarily unavailable. Please try again.');
      return response.json();
    },
    async load(more = false) {
      if (!this.isPublic || !this.shareId) return;
      const id = this.shareId; this.loading = true;
      try {
        const result = await this.request({}, more && this.next ? `?before=${encodeURIComponent(this.next)}` : '');
        if (this._closed || id !== this.shareId || !this.isPublic) return;
        this.notes = more ? [...this.notes, ...result.notes] : result.notes;
        this.count = result.count; this.next = result.next;
        this.$emit('change', this.notes);
      } catch (error) { if (this.opened) this.error = error.message; }
      finally { if (id === this.shareId) this.loading = false; }
    },
    async open() {
      if (!this.isPublic) { if (this.canPublish) this.$emit('publish'); return; }
      if (this.opened) return;
      this._trigger = document.activeElement; this._overflow = document.body.style.overflow;
      this.opened = true; this.error = ''; this.$emit('open');
      await this.$nextTick(); document.body.style.overflow = 'hidden'; this.$refs.dialog.showModal();
      this._stopBackdrop = initDialogBackdrop(this.$refs.dialog, this.close);
      this.$refs.dialog.querySelector('.view-dialog-close')?.focus({ preventScroll: true }); this.load();
    },
    close() { this._stopBackdrop?.(); this.$refs.dialog?.close(); this.opened = false; document.body.style.overflow = this._overflow || ''; this._trigger?.isConnected && this._trigger.focus({ preventScroll: true }); this.$emit('close'); },
    persist() { try { localStorage.setItem('view-note-ownership', JSON.stringify(this.owned)); } catch { /* A note can still be posted when storage is unavailable. */ } },
    async submit() {
      if (!this.isPublic || this.sending || !this.text.trim()) return;
      this.sending = true; this.error = ''; this.success = false;
      try {
        const result = await this.request({ method: 'POST', body: JSON.stringify({ text: this.text.trim() }) });
        this.owned[result.note.id] = result.token; this.persist(); this.text = ''; this.success = true; await this.load();
      } catch (error) { this.error = error.message; }
      finally { this.sending = false; }
    },
    async remove(note) {
      this.deleting = note.id; this.error = ''; this.success = false;
      try { await this.request({ method: 'DELETE', body: JSON.stringify({ id: note.id, token: this.owned[note.id] }) }); delete this.owned[note.id]; this.persist(); await this.load(); }
      catch (error) { this.error = error.message; }
      finally { this.deleting = ''; }
    },
  },
};
</script>
